
CREATE DATABASE IF NOT EXISTS recruitment_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE recruitment_db;
CREATE TABLE roles(role_id INT AUTO_INCREMENT PRIMARY KEY,role_code VARCHAR(30) UNIQUE NOT NULL,role_name VARCHAR(80) NOT NULL,is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL,email VARCHAR(150) UNIQUE,role_id INT NOT NULL,status VARCHAR(20) DEFAULT 'ACTIVE',last_login_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(role_id)) ENGINE=InnoDB;
CREATE TABLE candidates(candidate_id INT AUTO_INCREMENT PRIMARY KEY,candidate_code VARCHAR(30) UNIQUE NOT NULL,full_name VARCHAR(150) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,mobile VARCHAR(20) UNIQUE NOT NULL,date_of_birth DATE NULL,gender VARCHAR(20),qualification VARCHAR(80) NOT NULL,college VARCHAR(180),university VARCHAR(180),passing_year SMALLINT NOT NULL,percentage DECIMAL(5,2),cgpa DECIMAL(4,2),backlog_count INT DEFAULT 0,primary_technology VARCHAR(80),current_location VARCHAR(100),preferred_location VARCHAR(100),profile_status VARCHAR(20) DEFAULT 'ACTIVE',placement_status VARCHAR(20) DEFAULT 'NOT_PLACED',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(primary_technology),INDEX(passing_year),INDEX(placement_status)) ENGINE=InnoDB;
CREATE TABLE skills(skill_id INT AUTO_INCREMENT PRIMARY KEY,skill_name VARCHAR(100) UNIQUE NOT NULL,category VARCHAR(60),is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE candidate_skills(candidate_skill_id INT AUTO_INCREMENT PRIMARY KEY,candidate_id INT NOT NULL,skill_id INT NOT NULL,proficiency_level VARCHAR(20),years_experience DECIMAL(4,1) DEFAULT 0,is_primary TINYINT(1) DEFAULT 0,UNIQUE(candidate_id,skill_id),INDEX(candidate_id),INDEX(skill_id),FOREIGN KEY(candidate_id) REFERENCES candidates(candidate_id),FOREIGN KEY(skill_id) REFERENCES skills(skill_id)) ENGINE=InnoDB;
CREATE TABLE companies(company_id INT AUTO_INCREMENT PRIMARY KEY,company_code VARCHAR(30) UNIQUE NOT NULL,company_name VARCHAR(180) NOT NULL,industry VARCHAR(100),website VARCHAR(200),location VARCHAR(120),company_type VARCHAR(30),hr_name VARCHAR(120),hr_email VARCHAR(150),hr_mobile VARCHAR(20),status VARCHAR(20) DEFAULT 'ACTIVE',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(company_name),INDEX(status)) ENGINE=InnoDB;
CREATE TABLE jobs(job_id INT AUTO_INCREMENT PRIMARY KEY,job_code VARCHAR(40) UNIQUE NOT NULL,company_id INT NOT NULL,job_title VARCHAR(150) NOT NULL,employment_type VARCHAR(30) DEFAULT 'FULL_TIME',location VARCHAR(120) NOT NULL,openings INT NOT NULL,min_package_lpa DECIMAL(6,2),max_package_lpa DECIMAL(6,2),min_percentage DECIMAL(5,2),min_passing_year SMALLINT,max_passing_year SMALLINT,max_backlogs INT DEFAULT 0,experience_min_years DECIMAL(4,1) DEFAULT 0,qualification_rule VARCHAR(255),posted_date DATE NOT NULL,application_deadline DATE NOT NULL,status VARCHAR(20) DEFAULT 'OPEN',created_by INT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(company_id),INDEX(status),INDEX(application_deadline),INDEX(location),FOREIGN KEY(company_id) REFERENCES companies(company_id),FOREIGN KEY(created_by) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE job_skills(job_skill_id INT AUTO_INCREMENT PRIMARY KEY,job_id INT NOT NULL,skill_id INT NOT NULL,minimum_level VARCHAR(20),mandatory_flag TINYINT(1) DEFAULT 1,UNIQUE(job_id,skill_id),FOREIGN KEY(job_id) REFERENCES jobs(job_id),FOREIGN KEY(skill_id) REFERENCES skills(skill_id)) ENGINE=InnoDB;
CREATE TABLE applications(application_id INT AUTO_INCREMENT PRIMARY KEY,application_code VARCHAR(40) UNIQUE NOT NULL,candidate_id INT NOT NULL,job_id INT NOT NULL,applied_at DATETIME DEFAULT CURRENT_TIMESTAMP,eligibility_status VARCHAR(20) DEFAULT 'PENDING',eligibility_reason VARCHAR(500),application_status VARCHAR(30) DEFAULT 'APPLIED',source VARCHAR(50),assigned_recruiter_id INT NULL,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(candidate_id,job_id),INDEX(application_status),INDEX(assigned_recruiter_id),FOREIGN KEY(candidate_id) REFERENCES candidates(candidate_id),FOREIGN KEY(job_id) REFERENCES jobs(job_id),FOREIGN KEY(assigned_recruiter_id) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE application_history(history_id BIGINT AUTO_INCREMENT PRIMARY KEY,application_id INT NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,remarks VARCHAR(500),changed_by INT NULL,changed_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(application_id),INDEX(changed_at),FOREIGN KEY(application_id) REFERENCES applications(application_id),FOREIGN KEY(changed_by) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE interview_rounds(interview_id INT AUTO_INCREMENT PRIMARY KEY,application_id INT NOT NULL,round_number INT NOT NULL,round_type VARCHAR(50) NOT NULL,scheduled_date DATE NOT NULL,scheduled_time TIME NULL,mode VARCHAR(20) NOT NULL,interviewer_name VARCHAR(120),meeting_or_location VARCHAR(255),status VARCHAR(20) DEFAULT 'SCHEDULED',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(application_id,round_number),INDEX(scheduled_date),INDEX(status),FOREIGN KEY(application_id) REFERENCES applications(application_id)) ENGINE=InnoDB;
CREATE TABLE interview_feedback(feedback_id INT AUTO_INCREMENT PRIMARY KEY,interview_id INT UNIQUE NOT NULL,technical_rating DECIMAL(3,1),communication_rating DECIMAL(3,1),problem_solving_rating DECIMAL(3,1),overall_rating DECIMAL(3,1),recommendation VARCHAR(30) NOT NULL,remarks TEXT,submitted_by INT NULL,submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(recommendation),FOREIGN KEY(interview_id) REFERENCES interview_rounds(interview_id),FOREIGN KEY(submitted_by) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE offers(offer_id INT AUTO_INCREMENT PRIMARY KEY,offer_code VARCHAR(40) UNIQUE NOT NULL,application_id INT UNIQUE NOT NULL,designation VARCHAR(120) NOT NULL,offered_package_lpa DECIMAL(6,2) NOT NULL,offer_date DATE NOT NULL,expected_joining_date DATE NULL,offer_status VARCHAR(20) DEFAULT 'OFFERED',remarks VARCHAR(500),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(offer_status),FOREIGN KEY(application_id) REFERENCES applications(application_id)) ENGINE=InnoDB;
CREATE TABLE placements(placement_id INT AUTO_INCREMENT PRIMARY KEY,candidate_id INT NOT NULL,company_id INT NOT NULL,job_id INT NOT NULL,offer_id INT UNIQUE NOT NULL,designation VARCHAR(120) NOT NULL,final_package_lpa DECIMAL(6,2) NOT NULL,expected_joining_date DATE NULL,actual_joining_date DATE NULL,joining_status VARCHAR(20) DEFAULT 'PENDING',placement_status VARCHAR(20) DEFAULT 'ACTIVE',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(candidate_id),INDEX(company_id),INDEX(joining_status),FOREIGN KEY(candidate_id) REFERENCES candidates(candidate_id),FOREIGN KEY(company_id) REFERENCES companies(company_id),FOREIGN KEY(job_id) REFERENCES jobs(job_id),FOREIGN KEY(offer_id) REFERENCES offers(offer_id)) ENGINE=InnoDB;
CREATE TABLE activity_logs(log_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,module_name VARCHAR(60) NOT NULL,action_name VARCHAR(80) NOT NULL,record_id VARCHAR(60),description VARCHAR(500),logged_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(module_name),INDEX(logged_at),FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE qualifications(qualification_id INT AUTO_INCREMENT PRIMARY KEY,qualification_name VARCHAR(80) UNIQUE NOT NULL,description VARCHAR(255),is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE locations(location_id INT AUTO_INCREMENT PRIMARY KEY,location_name VARCHAR(100) UNIQUE NOT NULL,state_name VARCHAR(100),country_name VARCHAR(100) DEFAULT 'India',is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
